      "applicability": "established",
      "finding": "conditional_qualified",
      "comment": "The guideline requires the person to experience early warning symptoms (awareness). The patient describes sweating and confusion but cannot organize self-treatment."
    },
    {
      "source_slot": 2,
      "patient_paragraph": 2,
      "applicability": "established",
      "finding": "conditional_qualified",
      "comment": "The guideline requires the person to be following a treatment regimen that minimises the risk of hypoglycaemia. The patient injects insulin but cannot name the preparation or dose."
    },
    {
      "source_slot": 4,
      "patient_paragraph": 2,
      "applicability": "established",
      "finding": "conditional_qualified",
      "comment": "The guideline requires self-monitoring of blood glucose levels before driving and every two hours during a journey. The patient has not brought three months of monitoring records."
    }
